-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Werkzeuge > - Mocking-Tools

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Mocking-Tools in der testgetriebenen Entwicklung (TDD) notwendig, um Abhängigkeiten zu isolieren?', 2, '[{"text": "Ja", "correct": true, "because": "Mocking isoliert externe Abhängigkeiten"}, {"text": "Nein", "correct": false, "because": "Isolation ist TDD-Kern"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Mocking-Tools in TDD ohne Test-Frameworks verwendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Test-Frameworks bieten Struktur für Mocks"}, {"text": "Ja", "correct": false, "because": "Kombination üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ersetzen Mocking-Tools in TDD die Notwendigkeit echter Integrationstests?', 2, '[{"text": "Nein", "correct": true, "because": "Mocks für Unit-Tests, Integration separat"}, {"text": "Ja", "correct": false, "because": "Integration bleibt nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Verwendung von Mocking-Tools in TDD die Testgeschwindigkeit erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Mocks vermeiden echte Abhängigkeiten"}, {"text": "Nein", "correct": false, "because": "Schnelligkeit ist Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Mocking-Tools in TDD nur für komplexe Projekte nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Breite Anwendbarkeit"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Mocking-Tools in TDD?', 2, '[{"text": "Isolation von Abhängigkeiten", "correct": true, "because": "Kernfunktion von Mocking"}, {"text": "Code-Optimierung", "correct": false, "because": "Nicht primär"}, {"text": "Dokumentation", "correct": false, "because": "Nebenprodukt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil von Mocking-Tools ist in TDD besonders wichtig?', 3, '[{"text": "Schnellere Testausführung", "correct": true, "because": "Vermeidet echte Abhängigkeiten"}, {"text": "Erhöhte Code-Komplexität", "correct": false, "because": "Nicht Ziel"}, {"text": "Manuelle Testvalidierung", "correct": false, "because": "Automatisierung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mocking-Tool ist für Java-basierte TDD-Projekte am bekanntesten?', 2, '[{"text": "Mockito", "correct": true, "because": "Weit verbreitet in Java"}, {"text": "Pytest", "correct": false, "because": "Python-Tool"}, {"text": "Jest", "correct": false, "because": "JavaScript-Tool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Mocking-Tools im Red-Green-Refactor-Zyklus?', 2, '[{"text": "Unterstützung der Rot-Phase", "correct": true, "because": "Mocks simulieren Verhalten"}, {"text": "Abschluss der Grün-Phase", "correct": false, "because": "Tests bestehen später"}, {"text": "Optimierung in Refactor", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist für Mocking-Tools in TDD entscheidend?', 2, '[{"text": "Flexibilität bei Simulation", "correct": true, "because": "Mocks passen sich an"}, {"text": "Hohe Laufzeitkosten", "correct": false, "because": "Effizienz wichtig"}, {"text": "Keine Testunterstützung", "correct": false, "because": "Tests zentral"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bieten Mocking-Tools in TDD?', 4, '[{"text": "Simulation von Abhängigkeiten", "correct": true, "because": "Kernfunktion"}, {"text": "Verhalten definieren", "correct": true, "because": "Mocks steuerbar"}, {"text": "Code-Generierung", "correct": false, "because": "Nicht Aufgabe"}, {"text": "Schnelle Testausführung", "correct": true, "because": "Effizienzsteigerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Mocking-Tools in TDD?', 3, '[{"text": "Isolation von Komponenten", "correct": true, "because": "Fokus auf Unit-Tests"}, {"text": "Frühe Fehlererkennung", "correct": true, "because": "Mocks zeigen Probleme"}, {"text": "Langsamere Tests", "correct": false, "because": "Schnelligkeit Vorteil"}, {"text": "Verbesserte Testbarkeit", "correct": true, "because": "Abhängigkeiten kontrollierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mocking-Tools sind in TDD-Projekten gängig?', 3, '[{"text": "Mockito (Java)", "correct": true, "because": "Beliebt für Java"}, {"text": "unittest.mock (Python)", "correct": true, "because": "Python-Standard"}, {"text": "Excel", "correct": false, "because": "Kein Mocking-Tool"}, {"text": "EasyMock (Java)", "correct": true, "because": "Alternative für Java"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Nutzung von Mocking-Tools in TDD?', 4, '[{"text": "Komplexität bei Einrichtung", "correct": true, "because": "Lernkurve vorhanden"}, {"text": "Wartung der Mocks", "correct": true, "because": "Änderungen nötig"}, {"text": "Keine Testunterstützung", "correct": false, "because": "Tests zentral"}, {"text": "Risiko von Fehlkonfiguration", "correct": true, "because": "Falsche Mocks möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen Mocking-Tools für TDD nützlich?', 3, '[{"text": "Schnelle Testzyklen", "correct": true, "because": "Effizienzsteigerung"}, {"text": "Kontrolle über Abhängigkeiten", "correct": true, "because": "Simulierbares Verhalten"}, {"text": "Hohe Kosten", "correct": false, "because": "Kosten meist gering"}, {"text": "Unterstützung für Unit-Tests", "correct": true, "because": "Isolation ermöglicht"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Mocking-Tools sind für TDD unerlässlich. b) Mocking-Tools erhöhen die Testgeschwindigkeit.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Nicht zwingend, aber Geschwindigkeit steigt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mocking-Tools simulieren externe Abhängigkeiten. b) Mocking-Tools ersetzen Integrationstests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Simulation ja, Ersatz nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mocking-Tools können die Testbarkeit verbessern. b) Mocking-Tools sind in TDD nur für Java geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Testbarkeit ja, Sprache flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Mocking-Tools erfordern keine Test-Frameworks. b) Mocking-Tools unterstützen den TDD-Zyklus.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Frameworks nötig, Zyklus unterstützt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mocking-Tools machen Tests schneller. b) Mocking-Tools sind für kleine Projekte ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schnelligkeit ja, Größe egal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

